def shortest_distance(n, edges, start, end):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))
    heap = [(0, start)]
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[start] = 0
    while heap:
        current_distance, current_node = heapq.heappop(heap)
        if current_node == end:
